5 |  *
6 |  * From a "bob run -f stream-json" event stream (one JSON object per line),
7 |  * join the "content" of assistant "message" events that come AFTER the LAST
8 |  * "tool_use" event.  Blank or non-JSON lines are silently ignored.
9 |  *
10 |  * When there is no tool_use event, all assistant message content is returned.
11 |  */
12 | function finalText(streamJsonl) {
13 | 	var lines = streamJsonl.split("\n");
14 | 	var events = [];
15 | 
16 | 	for (var i = 0; i < lines.length; i++) {
17 | 		var line = lines[i].trim();
18 | 		if (!line) continue;
19 | 		try {
20 | 			events.push(JSON.parse(line));
21 | 		} catch (e) {
22 | 			// ignore non-JSON lines
23 | 		}
24 | 	}
25 | 
26 | 	// Find index of last tool_use event
27 | 	var lastToolUse = -1;
28 | 	for (var j = 0; j < events.length; j++) {
29 | 		if (events[j].type === "tool_use") {
30 | 			lastToolUse = j;
31 | 		}
32 | 	}
